class METPurchOrderConfirmReportDesign
{
}

Method.Source:
/// <summary>
/// Get PO report name
/// </summary>
/// <param name = "_purchTable">Purchase order table</param>
/// <returns>PO report name</returns>
public static SRSCatalogItemName getPOReportDesign(PurchTable _purchTable)
{
    SRSCatalogItemName  reportName = '';        

    if (_purchTable)
    {
        if (_purchTable.vendTable_OrderAccount().VendGroup == METConstants::ImportPOVendorGroup && _purchTable.PurchPoolId == METConstants::ImportPOPoolId)
        {
            reportName = ssrsReportStr(METPurchPurchaseOrder, ReportImport);
        }
        else
        {
            reportName = ssrsReportStr(METPurchPurchaseOrder, ReportTrade);
        }

        if (_purchTable.getCountOflines() == _purchTable.getCountOfLinesWithNegativeQty())
        {
            reportName = ssrsReportStr(METPurchPurchaseOrder, ReportReturn);
        }
    }
    return reportName;
}
